// TP : PWM + filtre RC = convertisseur numérique-analogique.
// D9 produit une PWM à 490 Hz ; R1 (10 kΩ) et C1 (100 µF) n'en gardent que la valeur moyenne.
const int SORTIE = 9;

void setup() {
  Serial.begin(9600);
  pinMode(SORTIE, OUTPUT);
  analogWrite(SORTIE, 128);                 // rapport cyclique 128/255 ≈ 50 % → environ 2,5 V
}

void loop() {
  float u = analogRead(A0) * 5.0 / 1023;   // tension du condensateur, en volts
  Serial.print("tension:");
  Serial.println(u);
  delay(50);                                // 20 mesures par seconde
}
